"""Disposable, loopback-only Docker smoke checks for native TLS and proxied /ws.

The orchestrator owns image builds, Compose creation, readiness, and final cleanup.
This module only mutates that project's connectionserver and its generated test PEMs.
No application login or production credential is needed: WHO answers at the login screen.
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
from pathlib import Path
import re
import secrets
import shutil
import socket
import ssl
import stat
import struct
import subprocess
import tempfile
import time


TLS_TARGET = "/run/sharpmush-tls"
WHO_MARKER = b"players connected."
LIMIT = 1024 * 1024
TIMEOUT = 40
WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"


def _run(argv: list[str], *, check: bool = True, timeout: int = 120):
    names = ("PATH", "HOME", "USER", "LANG", "LC_ALL", "TMPDIR", "TERM")
    environment = {key: os.environ[key] for key in names if key in os.environ}
    result = subprocess.run(argv, capture_output=True, text=True, timeout=timeout, env=environment)
    if check and result.returncode:
        raise RuntimeError(f"Command failed ({argv[0]}): {result.stderr[-3000:]}")
    return result


def _authority(cert_dir: Path) -> Path:
    return cert_dir.parent / (cert_dir.name + "-smoke-authority")


def _assert_generated(cert_dir: Path) -> None:
    marker = _authority(cert_dir) / "fixture.json"
    if not marker.is_file() or json.loads(marker.read_text()).get("cert_dir") != str(cert_dir.resolve()):
        raise ValueError("Refusing to modify certificates not generated by this smoke test")
    if cert_dir.is_symlink() or any((cert_dir / name).is_symlink() for name in ("ca.pem", "fullchain.pem", "privkey.pem")):
        raise ValueError("Generated certificate files must not be symlinks")


def _issue_leaf(cert_dir: Path) -> None:
    authority = _authority(cert_dir)
    key, request, leaf = [authority / name for name in ("leaf.key", "leaf.csr", "leaf.pem")]
    extensions = authority / "leaf.ext"
    extensions.write_text(
        "basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature,keyEncipherment\n"
        "extendedKeyUsage=serverAuth\nsubjectAltName=DNS:localhost,IP:127.0.0.1\n"
        "subjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid,issuer\n"
    )
    _run(["openssl", "req", "-new", "-newkey", "rsa:2048", "-nodes", "-subj", "/CN=localhost",
          "-keyout", str(key), "-out", str(request)])
    _run(["openssl", "x509", "-req", "-in", str(request), "-CA", str(authority / "issuer.pem"),
          "-CAkey", str(authority / "issuer.key"), "-set_serial", "0x" + secrets.token_hex(16),
          "-days", "1", "-extfile", str(extensions), "-out", str(leaf)])
    # Existing files retain owner/group/mode on renewal; finish the pair before restarting.
    (cert_dir / "fullchain.pem").write_bytes(leaf.read_bytes() + (authority / "issuer.pem").read_bytes())
    (cert_dir / "privkey.pem").write_bytes(key.read_bytes())
    key.chmod(0o600)


def generate_certificates(cert_dir: Path) -> Path:
    """Create throwaway root/intermediate/leaf fixtures; never overwrite existing material."""
    cert_dir = Path(cert_dir).resolve()
    authority = _authority(cert_dir)
    if authority.exists() or (cert_dir.exists() and any(cert_dir.iterdir())):
        raise ValueError("Certificate fixture destinations must be new or empty")
    cert_dir.mkdir(parents=True, exist_ok=True)
    authority.mkdir(mode=0o700)
    (authority / "fixture.json").write_text(json.dumps({"cert_dir": str(cert_dir)}))
    root_key, root = authority / "root.key", authority / "root.pem"
    _run(["openssl", "req", "-x509", "-newkey", "rsa:2048", "-nodes", "-days", "3",
          "-subj", "/CN=SharpMUSH disposable smoke root", "-keyout", str(root_key), "-out", str(root),
          "-addext", "basicConstraints=critical,CA:TRUE,pathlen:1",
          "-addext", "keyUsage=critical,keyCertSign,cRLSign"])
    root_key.chmod(0o600)
    _run(["openssl", "req", "-new", "-newkey", "rsa:2048", "-nodes",
          "-subj", "/CN=SharpMUSH disposable smoke intermediate",
          "-keyout", str(authority / "issuer.key"), "-out", str(authority / "issuer.csr")])
    (authority / "issuer.key").chmod(0o600)
    extensions = authority / "issuer.ext"
    extensions.write_text("basicConstraints=critical,CA:TRUE,pathlen:0\nkeyUsage=critical,keyCertSign,cRLSign\n"
                          "subjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid,issuer\n")
    _run(["openssl", "x509", "-req", "-in", str(authority / "issuer.csr"), "-CA", str(root),
          "-CAkey", str(root_key), "-set_serial", "0x" + secrets.token_hex(16), "-days", "2",
          "-extfile", str(extensions), "-out", str(authority / "issuer.pem")])
    (cert_dir / "ca.pem").write_bytes(root.read_bytes())
    _issue_leaf(cert_dir)
    (cert_dir / "privkey.pem").chmod(0o600)
    if os.environ.get("GITHUB_ACTIONS") == "true":
        prepare_certificate_permissions(cert_dir)
    return cert_dir / "ca.pem"


def cleanup_certificates(cert_dir: Path) -> None:
    """Remove all generated private material, including an interrupted issuance's CA keys."""
    cert_dir = Path(cert_dir).resolve()
    authority = _authority(cert_dir)
    if not authority.exists():
        return
    _assert_generated(cert_dir)
    (cert_dir / "privkey.pem").unlink(missing_ok=True)
    shutil.rmtree(authority)


def prepare_certificate_permissions(cert_dir: Path) -> None:
    """CI-only ownership of our throwaway files; never change a host security setting."""
    cert_dir = Path(cert_dir).resolve()
    _assert_generated(cert_dir)
    if os.environ.get("GITHUB_ACTIONS") != "true":
        raise ValueError("The sudo fixture-permission step is restricted to the disposable CI runner")
    files = [cert_dir / name for name in ("ca.pem", "fullchain.pem", "privkey.pem")]
    _run(["sudo", "-n", "chgrp", "1654", str(cert_dir), *map(str, files)])
    cert_dir.chmod(0o750)
    for path in files:
        path.chmod(0o640)


def renew_certificates(cert_dir: Path) -> None:
    cert_dir = Path(cert_dir).resolve()
    _assert_generated(cert_dir)
    _issue_leaf(cert_dir)


def _tls_context(ca: Path) -> ssl.SSLContext:
    # Explicit CA only: do not inherit the machine's trust anchors or bypass hostname checking.
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    context.minimum_version = ssl.TLSVersion.TLSv1_2
    context.load_verify_locations(cafile=str(ca))
    return context


def _connect_tls(port: int, ca: Path, hostname: str = "localhost") -> ssl.SSLSocket:
    raw = socket.create_connection(("127.0.0.1", port), timeout=TIMEOUT)
    try:
        return _tls_context(ca).wrap_socket(raw, server_hostname=hostname)
    except BaseException:
        raw.close()
        raise


def _wait_tls(port: int, ca: Path) -> bytes:
    deadline = time.monotonic() + 90
    last_error = None
    while time.monotonic() < deadline:
        try:
            with _connect_tls(port, ca) as stream:
                return stream.getpeercert(binary_form=True)
        except ssl.SSLCertVerificationError:
            raise  # A wrong certificate is not a readiness condition.
        except (OSError, ssl.SSLError) as error:
            last_error = error
            time.sleep(1)
    raise TimeoutError(f"TLS listener did not become ready: {last_error}")


class _TelnetReader:
    """Minimal IAC parser: decline options so compression/markup cannot hide WHO output."""

    def __init__(self):
        self.state = "data"
        self.command = 0

    def feed(self, data: bytes) -> tuple[bytes, bytes]:
        text, reply = bytearray(), bytearray()
        for value in data:
            if self.state == "data":
                if value == 255:
                    self.state = "iac"
                else:
                    text.append(value)
            elif self.state == "iac":
                if value == 255:
                    text.append(value)
                    self.state = "data"
                elif value in (251, 252, 253, 254):
                    self.command, self.state = value, "option"
                elif value == 250:
                    self.state = "sub"
                else:
                    self.state = "data"
            elif self.state == "option":
                if self.command in (251, 253):
                    reply.extend((255, 254 if self.command == 251 else 252, value))
                self.state = "data"
            elif self.state == "sub" and value == 255:
                self.state = "sub-iac"
            elif self.state == "sub-iac":
                self.state = "data" if value == 240 else "sub"
        return bytes(text), bytes(reply)


def _telnet_who(stream: socket.socket) -> None:
    stream.sendall(b"WHO\r\n")
    reader, output = _TelnetReader(), bytearray()
    deadline = time.monotonic() + TIMEOUT
    while time.monotonic() < deadline:
        stream.settimeout(max(0.1, deadline - time.monotonic()))
        packet = stream.recv(16384)
        if not packet:
            raise RuntimeError("Telnet closed before WHO output arrived")
        text, reply = reader.feed(packet)
        if reply:
            stream.sendall(reply)
        output.extend(text)
        # The isolated world has no logged-in characters; this exact footer proves
        # the command traversed the socket owner, NATS, engine, and renderer.
        if WHO_MARKER in output:
            return
        if len(output) > LIMIT:
            break
    raise RuntimeError("WHO did not return the expected player-list footer")


def _read_exact(stream: socket.socket, length: int, deadline: float | None = None) -> bytes:
    chunks = bytearray()
    while len(chunks) < length:
        if deadline is not None:
            if time.monotonic() >= deadline:
                raise TimeoutError("WebSocket read deadline exceeded")
            stream.settimeout(max(0.1, deadline - time.monotonic()))
        packet = stream.recv(length - len(chunks))
        if not packet:
            raise RuntimeError("WebSocket closed during a frame")
        chunks.extend(packet)
    return bytes(chunks)


def _send_ws(stream: socket.socket, payload: bytes, opcode: int = 1) -> None:
    mask = secrets.token_bytes(4)
    length = len(payload)
    if length > LIMIT:
        raise ValueError("WebSocket payload exceeds smoke limit")
    prefix = bytes([0x80 | opcode])
    if length < 126:
        prefix += bytes([0x80 | length])
    elif length <= 65535:
        prefix += bytes([0xFE]) + struct.pack("!H", length)
    else:
        prefix += bytes([0xFF]) + struct.pack("!Q", length)
    stream.sendall(prefix + mask + bytes(value ^ mask[i % 4] for i, value in enumerate(payload)))


def _read_ws(stream: socket.socket, deadline: float | None = None) -> bytes:
    message = bytearray()
    deadline = deadline if deadline is not None else time.monotonic() + TIMEOUT
    while time.monotonic() < deadline:
        stream.settimeout(max(0.1, deadline - time.monotonic()))
        first, second = _read_exact(stream, 2, deadline)
        if first & 0x70 or second & 0x80:
            raise RuntimeError("Unexpected reserved bits or masked server WebSocket frame")
        opcode, length = first & 15, second & 127
        if length == 126:
            length = struct.unpack("!H", _read_exact(stream, 2, deadline))[0]
        elif length == 127:
            length = struct.unpack("!Q", _read_exact(stream, 8, deadline))[0]
        if length > LIMIT or len(message) + length > LIMIT:
            raise RuntimeError("WebSocket output exceeds smoke limit")
        payload = _read_exact(stream, length, deadline)
        if opcode == 8:
            raise RuntimeError("WebSocket closed before WHO output")
        if opcode == 9:
            _send_ws(stream, payload, opcode=10)
            continue
        if opcode == 10:
            continue
        if opcode not in (0, 1, 2):
            raise RuntimeError("Unexpected WebSocket opcode")
        message.extend(payload)
        if first & 0x80:
            return bytes(message)
    raise TimeoutError("WebSocket message deadline exceeded")


def websocket_who(port: int, ca: Path) -> None:
    with _connect_tls(port, ca) as stream:
        deadline = time.monotonic() + TIMEOUT
        key = base64.b64encode(secrets.token_bytes(16)).decode("ascii")
        request = (f"GET /ws HTTP/1.1\r\nHost: localhost:{port}\r\nUpgrade: websocket\r\n"
                   f"Connection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n"
                   f"Origin: https://localhost:{port}\r\n\r\n")
        stream.sendall(request.encode("ascii"))
        headers = bytearray()
        # Bytewise here avoids swallowing the beginning of the first WebSocket frame.
        while not headers.endswith(b"\r\n\r\n"):
            headers.extend(_read_exact(stream, 1, deadline))
            if len(headers) > 16384:
                raise RuntimeError("WebSocket HTTP headers exceed smoke limit")
        lines = headers.decode("iso-8859-1").split("\r\n")
        if not lines[0].startswith("HTTP/1.1 101 "):
            raise RuntimeError(f"Proxy /ws upgrade failed: {lines[0]}")
        fields = dict(line.lower().split(":", 1) for line in lines[1:] if ":" in line)
        expected = base64.b64encode(hashlib.sha1((key + WS_GUID).encode("ascii")).digest()).decode("ascii")
        # Header values are case-sensitive for Sec-WebSocket-Accept; parse it separately.
        accept = next((line.split(":", 1)[1].strip() for line in lines if line.lower().startswith("sec-websocket-accept:")), "")
        if accept != expected or fields.get("upgrade", "").strip() != "websocket":
            raise RuntimeError("Proxy /ws returned an invalid WebSocket upgrade")
        _send_ws(stream, b'{"type":"hello"}')
        _send_ws(stream, b"WHO")
        output = bytearray()
        for _ in range(100):
            frame = _read_ws(stream, deadline)
            try:
                envelope = json.loads(frame)
            except (ValueError, UnicodeDecodeError):
                envelope = None
            if isinstance(envelope, dict):
                if envelope.get("type") != "seq":
                    continue  # Never log or persist resume tokens.
                frame = str(envelope.get("data", "")).encode("utf-8")
            output.extend(frame)
            if WHO_MARKER in output:
                _send_ws(stream, struct.pack("!H", 1000), opcode=8)
                return
            if len(output) > LIMIT:
                break
        raise RuntimeError("Proxy WebSocket did not carry WHO output")


def _validate_isolation(compose: list[str], cert_dir: Path) -> str:
    if compose[:2] != ["docker", "compose"] or "--project-name" not in compose:
        raise ValueError("An explicit Docker Compose smoke project is required")
    project = compose[compose.index("--project-name") + 1]
    if not re.fullmatch(r"smush-smoke-[a-z0-9-]+", project):
        raise ValueError("Refusing a non-smoke Compose project")
    _assert_generated(cert_dir)
    if _run(["docker", "context", "show"]).stdout.strip() != "default":
        raise ValueError("Only the default Docker context is allowed")
    model = json.loads(_run(compose + ["config", "--format", "json"]).stdout)
    if model.get("name") != project:
        raise ValueError("Compose resolved a different project name")
    for service in model["services"].values():
        if service.get("container_name") and not service["container_name"].startswith(project + "-"):
            raise ValueError("Fixed non-smoke container names must be removed by the orchestrator")
        for port in service.get("ports", []):
            if port.get("published") and port.get("host_ip") != "127.0.0.1":
                raise ValueError("Every published smoke port must bind to 127.0.0.1")
    mounts = model["services"]["connectionserver"].get("volumes", [])
    certificate = [mount for mount in mounts if mount.get("target") == TLS_TARGET]
    if len(certificate) != 1 or Path(certificate[0]["source"]).resolve() != cert_dir:
        raise ValueError("Socket owner does not mount the generated fixture directory")
    if certificate[0].get("type") != "bind" or certificate[0].get("read_only") is not True:
        raise ValueError("Certificate mount must be a read-only bind")
    return project


def _container(compose: list[str], project: str) -> str:
    identifiers = _run(compose + ["ps", "--all", "--quiet", "connectionserver"]).stdout.split()
    if len(identifiers) != 1 or not re.fullmatch(r"[0-9a-f]{12,64}", identifiers[0]):
        raise RuntimeError("Expected exactly one disposable socket-owner container")
    identifier = identifiers[0]
    actual = _run(["docker", "inspect", "--format", '{{index .Config.Labels "com.docker.compose.project"}}', identifier]).stdout.strip()
    if actual != project:
        raise ValueError("Socket-owner container belongs to a different project")
    return identifier


def _restore_connectionserver(compose: list[str], tls_port: int, ca: Path) -> None:
    _run(compose + ["up", "-d", "--no-deps", "--no-build", "--pull", "never", "--force-recreate", "connectionserver"])
    _wait_tls(tls_port, ca)


def _negative_mount_and_permissions(compose: list[str], project: str, tls_port: int, cert_dir: Path) -> None:
    ca, key = cert_dir / "ca.pem", cert_dir / "privkey.pem"
    with tempfile.TemporaryDirectory(prefix="smoke-tls-negative-", dir=cert_dir.parent) as temporary:
        folder = Path(temporary)
        missing = folder / "must-not-be-created"
        override = folder / "negative.json"
        override.write_text(json.dumps({"services": {"connectionserver": {
            "restart": "no", "volumes": [{"type": "bind", "source": str(missing),
                "target": TLS_TARGET, "read_only": True, "bind": {"create_host_path": False}}]}}}))
        try:
            result = _run(compose + ["-f", str(override), "up", "-d", "--no-deps", "--no-build",
                                    "--pull", "never", "--force-recreate", "connectionserver"], check=False)
            if result.returncode == 0 or missing.exists() or "bind" not in (result.stdout + result.stderr).lower():
                raise RuntimeError("Docker did not reject the missing certificate bind without creating it")
        finally:
            _restore_connectionserver(compose, tls_port, ca)
        print("TLS smoke: Docker rejected the missing certificate directory", flush=True)

        mode = stat.S_IMODE(key.stat().st_mode)
        override.write_text(json.dumps({"services": {"connectionserver": {"restart": "no"}}}))
        try:
            key.chmod(0)
            _run(compose + ["exec", "-T", "connectionserver", "sh", "-c", f"test ! -r {TLS_TARGET}/privkey.pem"])
            _run(compose + ["-f", str(override), "up", "-d", "--no-deps", "--no-build",
                           "--pull", "never", "--force-recreate", "connectionserver"])
            identifier = _container(compose, project)
            deadline = time.monotonic() + TIMEOUT
            while time.monotonic() < deadline:
                state = json.loads(_run(["docker", "inspect", "--format", "{{json .State}}", identifier]).stdout)
                if state["Status"] == "exited":
                    break
                time.sleep(1)
            else:
                raise RuntimeError("Socket owner did not exit after losing private-key read access")
            if state["ExitCode"] == 0:
                raise RuntimeError("Unreadable-key startup unexpectedly exited successfully")
            logs = _run(compose + ["logs", "--no-color", "--tail", "100", "connectionserver"]).stdout
            if "privkey.pem" not in logs or "denied" not in logs.lower():
                raise RuntimeError("Startup failure did not identify private-key access denial")
            try:
                with socket.create_connection(("127.0.0.1", tls_port), timeout=2):
                    raise RuntimeError("TLS port still accepted TCP after failed startup")
            except OSError:
                pass
        finally:
            key.chmod(mode)
            _restore_connectionserver(compose, tls_port, ca)
        print("TLS smoke: UID 1654 cannot start with an unreadable private key", flush=True)


def run_tls_checks(compose: list[str], *, tls_port: int, plaintext_port: int,
                   websocket_port: int, cert_dir: Path) -> None:
    """Exercise only the supplied, disposable, ready Compose project; restore it on failures."""
    cert_dir = Path(cert_dir).resolve()
    project = _validate_isolation(compose, cert_dir)
    _container(compose, project)
    _run(compose + ["exec", "-T", "connectionserver", "sh", "-c",
                   f'test "$(id -u):$(id -g)" = "1654:1654" && test -r {TLS_TARGET}/fullchain.pem && test -r {TLS_TARGET}/privkey.pem'])
    ca = cert_dir / "ca.pem"
    initial = _wait_tls(tls_port, ca)
    with _connect_tls(tls_port, ca) as stream:
        _telnet_who(stream)
    with socket.create_connection(("127.0.0.1", plaintext_port), timeout=TIMEOUT) as stream:
        _telnet_who(stream)
    websocket_who(websocket_port, ca)
    print("TLS smoke: verified TLS, plaintext WHO, and Caddy /ws upgrade plus WHO output passed", flush=True)

    try:
        with _connect_tls(tls_port, ca, hostname="wrong-host.invalid"):
            raise RuntimeError("TLS unexpectedly accepted the wrong hostname")
    except ssl.SSLCertVerificationError:
        pass
    with socket.create_connection(("127.0.0.1", tls_port), timeout=TIMEOUT) as raw:
        untrusted_context = ssl.create_default_context()
        untrusted_context.minimum_version = ssl.TLSVersion.TLSv1_2
        try:
            with untrusted_context.wrap_socket(raw, server_hostname="localhost"):
                raise RuntimeError("TLS unexpectedly trusted the private smoke CA")
        except ssl.SSLCertVerificationError:
            pass
    print("TLS smoke: client rejected wrong hostname and untrusted issuer", flush=True)

    _negative_mount_and_permissions(compose, project, tls_port, cert_dir)
    with _connect_tls(tls_port, ca) as existing:
        renew_certificates(cert_dir)
        _run(compose + ["restart", "connectionserver"], timeout=150)
        replacement = _wait_tls(tls_port, ca)
        if replacement == initial:
            raise RuntimeError("Socket-owner restart did not present the replacement certificate")
        existing.settimeout(10)
        for _ in range(100):
            try:
                packet = existing.recv(16384)
                if not packet:
                    break
            except (ssl.SSLEOFError, ConnectionResetError):
                break
        else:
            raise RuntimeError("Old TLS connection survived the socket-owner restart")
    with _connect_tls(tls_port, ca) as stream:
        _telnet_who(stream)
    websocket_who(websocket_port, ca)
    print("TLS smoke: renewed certificate loaded after disconnecting restart; native and /ws output recovered", flush=True)
